$ErrorActionPreference='Stop'
$Root=(Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path; Set-Location $Root
$State=Join-Path $Root '.jaco\candidate';New-Item -ItemType Directory -Force -Path $State|Out-Null
$CorePort=if($env:JACO_CANDIDATE_CORE_PORT){[int]$env:JACO_CANDIDATE_CORE_PORT}else{3020};$SentinelPort=if($env:JACO_CANDIDATE_SENTINEL_PORT){[int]$env:JACO_CANDIDATE_SENTINEL_PORT}else{3299};$A2APort=if($env:JACO_CANDIDATE_A2A_PORT){[int]$env:JACO_CANDIDATE_A2A_PORT}else{3298};$CanonicalPort=if($env:JACO_CANONICAL_PORT){[int]$env:JACO_CANONICAL_PORT}else{3000}
if(-not(Get-Command node -ErrorAction SilentlyContinue)){throw 'Node 22+ required'};$major=[int]((& node -p "process.versions.node.split('.')[0]").Trim());if($major -lt 22){throw 'Node 22+ required'}
foreach($p in @($CorePort,$SentinelPort,$A2APort)){if(Get-NetTCPConnection -State Listen -LocalPort $p -ErrorAction SilentlyContinue){throw "candidate port $p occupied"}}
try{(Invoke-RestMethod -TimeoutSec 2 "http://127.0.0.1:$CanonicalPort/api/runtime/identity")|ConvertTo-Json -Depth 8|Set-Content (Join-Path $State 'canonical-before.json')}catch{'{}'|Set-Content (Join-Path $State 'canonical-before.json')}
function New-JacoBearer { $bytes=New-Object byte[] 32; [System.Security.Cryptography.RandomNumberGenerator]::Fill($bytes); return [Convert]::ToBase64String($bytes).TrimEnd('=').Replace('+','-').Replace('/','_') }
$Token=New-JacoBearer;$SentinelToken=New-JacoBearer;$A2AToken=New-JacoBearer;@("JACO_CONTINUUM_TOKEN=$Token","JACO_CONTINUUM_SENTINEL_BEARER=$SentinelToken","JACO_A2A_BEARER=$A2AToken")|Set-Content (Join-Path $State 'candidate.env')
$old=@{JACO_CONTINUUM_HOST=$env:JACO_CONTINUUM_HOST;JACO_CONTINUUM_PORT=$env:JACO_CONTINUUM_PORT;JACO_CONTINUUM_TOKEN=$env:JACO_CONTINUUM_TOKEN;JACO_SUBSTRATE_URL=$env:JACO_SUBSTRATE_URL;JACO_CONTINUUM_AUTOSTART=$env:JACO_CONTINUUM_AUTOSTART;JACO_CONTINUUM_SENTINEL_HOST=$env:JACO_CONTINUUM_SENTINEL_HOST;JACO_CONTINUUM_SENTINEL_PORT=$env:JACO_CONTINUUM_SENTINEL_PORT;JACO_CONTINUUM_URL=$env:JACO_CONTINUUM_URL;JACO_CONTINUUM_SENTINEL_BEARER=$env:JACO_CONTINUUM_SENTINEL_BEARER;JACO_A2A_HOST=$env:JACO_A2A_HOST;JACO_A2A_PORT=$env:JACO_A2A_PORT;JACO_BASE_URL=$env:JACO_BASE_URL;JACO_A2A_BEARER=$env:JACO_A2A_BEARER}
try{
 $env:JACO_CONTINUUM_HOST='127.0.0.1';$env:JACO_CONTINUUM_PORT="$CorePort";$env:JACO_CONTINUUM_TOKEN=$Token;$env:JACO_SUBSTRATE_URL="http://127.0.0.1:$CanonicalPort";$env:JACO_CONTINUUM_AUTOSTART='1';$core=Start-Process node -ArgumentList 'src/server/continuum/standalone-server.mjs' -WorkingDirectory $Root -RedirectStandardOutput (Join-Path $State 'core.out.log') -RedirectStandardError (Join-Path $State 'core.err.log') -PassThru
 Start-Sleep 1;$id=Invoke-RestMethod -TimeoutSec 5 "http://127.0.0.1:$CorePort/api/runtime/identity";if($id.releaseId -ne 'runtime'){throw 'identity mismatch'}
 $env:JACO_CONTINUUM_SENTINEL_HOST='127.0.0.1';$env:JACO_CONTINUUM_SENTINEL_PORT="$SentinelPort";$env:JACO_CONTINUUM_URL="http://127.0.0.1:$CorePort";$env:JACO_CONTINUUM_SENTINEL_BEARER=$SentinelToken;$sentinel=Start-Process node -ArgumentList 'src/continuum-sentinel.mjs' -WorkingDirectory (Join-Path $Root 'gateway') -RedirectStandardOutput (Join-Path $State 'sentinel.out.log') -RedirectStandardError (Join-Path $State 'sentinel.err.log') -PassThru
 $env:JACO_A2A_HOST='127.0.0.1';$env:JACO_A2A_PORT="$A2APort";$env:JACO_BASE_URL="http://127.0.0.1:$CorePort";$env:JACO_A2A_BEARER=$A2AToken;$a2a=Start-Process node -ArgumentList 'src/a2a-server.mjs' -WorkingDirectory (Join-Path $Root 'gateway') -RedirectStandardOutput (Join-Path $State 'a2a.out.log') -RedirectStandardError (Join-Path $State 'a2a.err.log') -PassThru
 Start-Sleep 1;$sh=Invoke-RestMethod -TimeoutSec 5 "http://127.0.0.1:$SentinelPort/health";$ah=Invoke-RestMethod -TimeoutSec 5 "http://127.0.0.1:$A2APort/health";$h=@{'x-jaco-continuum-token'=$Token};$cs=Invoke-RestMethod -Headers $h -TimeoutSec 5 "http://127.0.0.1:$CorePort/api/continuum/status";$ci=Invoke-RestMethod -Headers $h -TimeoutSec 5 "http://127.0.0.1:$CorePort/api/continuum/integrity";if(-not $ci.integrity.valid){throw 'integrity gate failed'}
 $proof=@{schema='jaco.continuum.candidate-proof.v1';releaseId=$id.releaseId;verifiedAt=(Get-Date).ToUniversalTime().ToString('o');architecture='SIDECAR_CONTROL_PLANE';ports=@{continuum=$CorePort;sentinel=$SentinelPort;a2a=$A2APort};executionSubstrate=@{port=$CanonicalPort};pids=@{continuum=$core.Id;sentinel=$sentinel.Id;a2a=$a2a.Id};checks=@{identity=$true;continuumStatus=$cs.success;eventIntegrity=$ci.integrity.valid;sentinelHealth=($sh.version -eq '0.22.0');a2aHealth=($ah.version -eq '0.22.0')};truthBoundary='TARGET_CANDIDATE_RUNTIME_VERIFIED; SUBSTRATE_CAPABILITIES_SEPARATELY_VERIFIED'};$proof|ConvertTo-Json -Depth 8|Set-Content (Join-Path $State 'candidate-proof.json');Write-Host "PASS Continuum sidecar READY $CorePort/$SentinelPort/$A2APort; canonical $CanonicalPort untouched" -ForegroundColor Green
}finally{foreach($k in $old.Keys){if($null -eq $old[$k]){Remove-Item "Env:$k" -ErrorAction SilentlyContinue}else{Set-Item "Env:$k" $old[$k]}}}
